+        const opt = (value: boolean) => ({
+            value,
+            default: false,
+            help: "",
+            type: "bool",
+        });
+        const add = (s, id: string) =>
+            reduceFlows(
+                s,
+                flowActions.FLOWS_ADD({
+                    flow: { ...TFlow(), id },
+                    matching_filters: {},
+                }),
+            );
+        const reversed = () =>
+            reduceFlows(
+                undefined,
+                OPTIONS_UPDATE({ view_order_reversed: opt(true) }),
+            );
+
+        it("reads the option from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+            const received = reduceFlows(
+                undefined,
+                // @ts-expect-error partial options are sufficient here
+                OPTIONS_RECEIVE({ view_order_reversed: opt(true) }),
+            );
+            expect(received.viewOrderReversed).toBe(true);
+            expect(reversed().viewOrderReversed).toBe(true);
+            expect(
+                reduceFlows(
+                    reversed(),
+                    OPTIONS_UPDATE({ view_order_reversed: opt(false) }),
+                ).viewOrderReversed,
+            ).toBe(false);
+        });
+        it("inserts new flows at the front when reversed", () => {
+            const s = add(add(add(reversed(), "a"), "b"), "c");
+            expect(s.view.map((f) => f.id)).toEqual(["c", "b", "a"]);
+            expect(s._viewIndex.get("c")).toBe(0);
+            expect(s._viewIndex.get("a")).toBe(2);
+        });
+        it("appends new flows when not reversed", () => {
+            const s = add(add(add(undefined, "a"), "b"), "c");
+            expect(s.view.map((f) => f.id)).toEqual(["a", "b", "c"]);
+        });
+        it("prefers an active column sort", () => {
+            let s = reduceFlows(
+                reversed(),
+                flowActions.setSort({ column: "path", desc: false }),
+            );
+            for (const [id, path] of [
+                ["a", "/1"],
+                ["b", "/2"],
+                ["c", "/3"],
+            ]) {
+                s = reduceFlows(
+                    s,
+                    flowActions.FLOWS_ADD({
+                        flow: {
+                            ...TFlow(),
+                            id,
+                            request: { ...TFlow().request, path },
+                        },
+                        matching_filters: {},
+                    }),
+                );
+            }
+            expect(s.view.map((f) => f.id)).toEqual(["a", "b", "c"]);
+        });
+    });
